dev_open <- function() {
    if (identical(.Platform$OS.type, "unix"))
        x11(type = "Xlib")
    else
        windows()
    plot.new()
}
idle_uaf <- function() {
    dev_open()
    getGraphicsEvent(
        onIdle = function() {
            dev.off()
        }
    )
}
mouse_uaf <- function() {
    dev_open()
    title("Click anywhere to trigger")
    getGraphicsEvent(
        onMouseDown = function(buttons, x, y) {
            dev.off()
        }
    )
}
keybd_uaf <- function() {
    dev_open()
    title("Press any key to trigger")
    getGraphicsEvent(
        onKeybd = function(key) {
            dev.off()
        }
    )
}
